// ── Basic probability calculations ────────────────────────────
const outcomes = ['HH','HT','TH','TT']; // two fair coins
const P = event => event.length / outcomes.length;

const atLeastOneHead = outcomes.filter(o => o.includes('H'));
console.log('P(at least 1 head):', P(atLeastOneHead)); // 0.75

// Complement: P(no heads) = 1 - P(at least 1 head)
console.log('via complement:', 1 - P(outcomes.filter(o => !o.includes('H')))); // 0.75

// ── Conditional probability ───────────────────────────────────
// P(both heads | first is heads)
const firstHeads = outcomes.filter(o => o[0] === 'H'); // HH, HT
const bothHeads  = outcomes.filter(o => o === 'HH');  // HH
// P(both | first=H) = P(both ∩ first=H) / P(first=H) = (1/4)/(2/4) = 0.5
const conditional = bothHeads.length / firstHeads.length;
console.log('P(both heads | first heads):', conditional); // 0.5

// ── Bayes theorem: spam filter ────────────────────────────────
// P(spam) = 0.3, P(FREE|spam) = 0.8, P(FREE|legit) = 0.05
function bayesSpam(pSpam, pFreeGivenSpam, pFreeGivenLegit) {
  const pLegit = 1 - pSpam;
  const pFree  = pFreeGivenSpam * pSpam + pFreeGivenLegit * pLegit;
  return (pFreeGivenSpam * pSpam) / pFree; // P(spam | FREE)
}

console.log('P(spam | FREE):', bayesSpam(0.3, 0.8, 0.05).toFixed(4)); // 0.8727

// ── Expected value ────────────────────────────────────────────
// Die roll: faces 1-6, uniform probability
const die = [1, 2, 3, 4, 5, 6];
const expectedDie = die.reduce((sum, x) => sum + x * (1/6), 0);
console.log('E[die roll]:', expectedDie); // 3.5

// Expected number of coin flips until first head (geometric distribution)
// E[X] = 1/p for success probability p
const expectedFlips = 1 / 0.5;
console.log('E[flips until head]:', expectedFlips); // 2.0

// ── Linearity of expectation: QuickSort average comparisons ───
// For random pivot QuickSort on n elements:
// E[comparisons] = sum over all pairs (i,j): P(i and j are compared)
// P(i compared to j) = 2/(|rank(i)-rank(j)|+1)  — harmonic series argument
// Result: E[comparisons] = 2n*ln(n) ≈ 1.386 * n*log2(n)

function expectedQuicksortComparisons(n) {
  // Exact formula: 2 * sum_{i=1}^{n} sum_{j=i+1}^{n} 1/(j-i+1)
  // Simplified approximation: 2 * n * H(n) where H(n) = harmonic number
  let H = 0;
  for (let i = 1; i <= n; i++) H += 1 / i;
  return 2 * n * H;
}

console.log('E[QuickSort comps] n=10:', expectedQuicksortComparisons(10).toFixed(1)); // ~29.2
console.log('E[QuickSort comps] n=100:', expectedQuicksortComparisons(100).toFixed(1)); // ~943.5

// ── Monte Carlo: estimate π ──────────────────────────────────
function estimatePi(trials) {
  let inside = 0;
  // Use a fixed seed simulation (deterministic for display)
  // In real code: Math.random()
  let x = 0.5, y = 0.3; // simple pseudo values stand-in
  for (let i = 0; i < trials; i++) {
    // Linear congruential generator for reproducibility
    x = (x * 1664525 + 1013904223) % 1;
    if (x < 0) x = -x;
    y = (y * 22695477 + 1) % 1;
    if (y < 0) y = -y;
    const rx = x * 2 - 1, ry = y * 2 - 1;
    if (rx * rx + ry * ry <= 1) inside++;
  }
  return 4 * inside / trials;
}

console.log('π estimate (1000 trials):', estimatePi(1000).toFixed(3));
console.log('π estimate (100000 trials):', estimatePi(100000).toFixed(4));
console.log('Actual π:', Math.PI.toFixed(4));

// ── Independence check ─────────────────────────────────────────
// Two events A, B are independent if P(A∩B) = P(A)*P(B)
const pA = 0.4, pB = 0.3, pAandB = 0.12;
const independent = Math.abs(pAandB - pA * pB) < 1e-9;
console.log('A and B independent:', independent); // true (0.12 = 0.4*0.3)
